{
  "root": "main_stack",
  "state": {
    "studentData": [
      { "Student": "A", "Study Hours": 5, "Exam Score": 75 },
      { "Student": "B", "Study Hours": 8, "Exam Score": 90 },
      { "Student": "C", "Study Hours": 3, "Exam Score": 60 },
      { "Student": "D", "Study Hours": 7, "Exam Score": 85 },
      { "Student": "E", "Study Hours": 6, "Exam Score": 80 }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": [
        "insight_title",
        "insight_body",
        "data_title",
        "data_body",
        "student_table",
        "correlation_heading",
        "correlation_body"
      ]
    },
    "insight_title": {
      "type": "Text",
      "props": { "text": "Study Performance Insight", "variant": "h2" },
      "children": []
    },
    "insight_body": {
      "type": "Text",
      "props": { "text": "This data illustrates the relationship between the number of hours students spent studying and their corresponding exam scores, providing insights into academic performance trends.", "variant": "body" },
      "children": []
    },
    "data_title": {
      "type": "Text",
      "props": { "text": "Student Study Data", "variant": "h2" },
      "children": []
    },
    "data_body": {
      "type": "Text",
      "props": { "text": "Here is the data for five students:", "variant": "body" },
      "children": []
    },
    "student_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "Student", "label": "Student" },
          { "key": "Study Hours", "label": "Study Hours" },
          { "key": "Exam Score", "label": "Exam Score" }
        ],
        "statePath": "/studentData",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "correlation_heading": {
      "type": "Text",
      "props": { "text": "Apparent Correlation", "variant": "h3" },
      "children": []
    },
    "correlation_body": {
      "type": "Text",
      "props": { "text": "Based on the provided data, there appears to be a strong positive correlation between study hours and exam scores. As the number of hours students spent studying increases, their exam scores generally tend to increase as well. This suggests that more study time is associated with higher performance in exams for these students.", "variant": "body" },
      "children": []
    }
  }
}
